SELECT f.feed_id, f.feed_img_url, COUNT(l.like_id) AS likeCount,
CAST(SUM(CASE WHEN l.user_id = #{loginUserId} THEN 1 ELSE 0 END) AS SIGNED) > 0 AS isLikedByUser
false AS isLikedByUser
FROM feed_tb f LEFT JOIN like_tb l ON f.feed_id = l.feed_id
f.feed_id <= #{cursorFeedId}
AND f.user_id = #{targetUserId}
GROUP BY f.feed_id, f.feed_img_url ORDER BY f.feed_id DESC LIMIT #{size}

SELECT f.feed_id, f.feed_img_url, (SELECT COUNT(*) FROM like_tb WHERE feed_id = f.feed_id) AS likeCount, TRUE AS isLikedByUser FROM feed_tb f LEFT JOIN like_tb l ON f.feed_id = l.feed_id
l.user_id = #{userId}
AND f.feed_id <= #{cursorFeedId}
ORDER BY f.feed_id DESC LIMIT #{size}
